results.pipeline_sql:
SELECT AVG(explainability_score) AS avg_explainability_score
FROM creative_ai
WHERE region IN ('Europe', 'North America');

SELECT player, AVG(running_speed) AS avg_running_speed
FROM world_cup
GROUP BY player;

SELECT DISTINCT D.city
FROM Donors AS D
WHERE D.city NOT IN (SELECT P.city FROM Programs AS P);

SELECT MAX(energy_consumption) as max_energy_consumption
FROM green_buildings
WHERE country IN ('India', 'China', 'Japan');

results.baseline_sql:
SELECT id, city, co_ownership_cost, property_id, 
       co_ownership_cost - LAG(co_ownership_cost) OVER (ORDER BY id) AS cost_change
FROM co_ownership;

SELECT country, AVG(capacity) AS average_capacity
FROM projects
GROUP BY country;

SELECT e.type, e.programs * 1.0 / a.animals AS ratio
FROM education e
JOIN animal_population a ON e.type = a.type;

results.pipeline_sql:
SELECT AVG(investment_amount) 
FROM climate_finance_projects 
WHERE region = 'East Asia' AND investment_year >= (SELECT MAX(investment_year) - 5 FROM climate_finance_projects);

results.baseline_sql:
SELECT Department, 100.0 * SUM(CASE WHEN Gender != 'Male' THEN 1 ELSE 0 END) / COUNT(*) AS Diversity_Ratio
FROM Employees
GROUP BY Department;

SELECT country, COUNT(*) as client_count
FROM socially_responsible_loans
GROUP BY country;

SELECT COUNT(DISTINCT source) 
FROM articles 
WHERE category = 'investigative_journalism';

SELECT product_category, state, SUM(sales) * 100.0 / (SELECT SUM(sales) FROM sales) AS percentage
FROM sales
GROUP BY product_category, state;

SELECT SUM(CASE WHEN f.audit_passed THEN 1 ELSE 0 END) AS worker_count
FROM factories f
JOIN workers w ON f.id = w.factory_id;

SELECT AVG(trips) as avg_trips_per_day
FROM daily_trips
WHERE city IN ('Tokyo', 'Seoul');

SELECT facility_id, date, waste_amount, AVG(waste_amount) OVER (PARTITION BY facility_id ORDER BY date ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS moving_avg
FROM facility_waste
ORDER BY facility_id, date;

results.pipeline_sql:
SELECT facility_id, waste_amount, AVG(waste_amount) OVER (PARTITION BY facility_id ORDER BY date ROWS BETWEEN 5 PRECEDING AND CURRENT ROW) AS moving_average
FROM facility_waste
WHERE date >= DATE('now', '-6 months');

SELECT research_institutes.name, research_institutes.location
FROM research_institutes
WHERE research_institutes.focus LIKE '%Organic%' AND research_institutes.location NOT LIKE '%Midwest%';

