SELECT SUM(warehouse_o.quantity) + SUM(warehouse_p.quantity) AS total_quantity
FROM (
    SELECT quantity FROM warehouse_o WHERE item_type IN ('E', 'F')
    UNION ALL
    SELECT quantity FROM warehouse_p WHERE item_type IN ('E', 'F')
) AS combined_quantities;

